-- Permanent identifiers generated by the internal registration form are
-- reserved immediately and retained even when a registration is abandoned.
CREATE TABLE IF NOT EXISTS student_id_reservations (
  id VARCHAR(64) NOT NULL,
  reservation_token VARCHAR(64) NOT NULL,
  permanent_student_id VARCHAR(32) NOT NULL,
  admission_year SMALLINT NOT NULL,
  sequence_number INT UNSIGNED NOT NULL,
  reservation_status VARCHAR(16) NOT NULL DEFAULT 'RESERVED',
  student_id VARCHAR(64) NULL,
  reserved_by VARCHAR(64) NOT NULL,
  created_at DATETIME NOT NULL,
  consumed_at DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_student_id_reservation_token (reservation_token),
  UNIQUE KEY uq_student_id_reservation_permanent (permanent_student_id),
  UNIQUE KEY uq_student_id_reservation_sequence (admission_year, sequence_number),
  KEY idx_student_id_reservation_status (reservation_status, admission_year)
);

-- Store the fields in the existing student profile and family-contact records.
ALTER TABLE student_profiles
  ADD COLUMN IF NOT EXISTS home_address VARCHAR(500) NULL;

-- These master attributes are referenced by the existing enrollment and
-- academic repositories but were not materialized by every schema baseline.
ALTER TABLE students
  ADD COLUMN IF NOT EXISTS admission_type VARCHAR(32) NULL,
  ADD COLUMN IF NOT EXISTS is_test_record TINYINT(1) NOT NULL DEFAULT 0;

ALTER TABLE student_family_contacts
  ADD COLUMN IF NOT EXISTS email VARCHAR(254) NULL,
  ADD COLUMN IF NOT EXISTS occupation VARCHAR(255) NULL,
  ADD COLUMN IF NOT EXISTS national_id VARCHAR(100) NULL;

-- Only the four approved school leadership roles may register internally.
-- Existing role IDs and all other role permissions are left unchanged.
INSERT IGNORE INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r
JOIN permissions p ON p.permission_key = 'admissions.write'
WHERE r.role_key IN ('PROPRIETOR', 'HEADTEACHER', 'ASSISTANT_HEADTEACHER', 'SCHOOL_ADMIN');
